import static org.junit.Assert.*;

/** Real Android measure/layout tests with an inset content parent. */
@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk={28,34})
public class FullscreenLayout205Test {
 static final String[] IDS={"videoLayout","controller","commentlay","video","video_view","seekBar","bottommenulay"};
 static int id(String name){for(int i=0;i<IDS.length;i++)if(IDS[i].equals(name))return 0x7f080100+i;return 0;}
 static Context context(Activity activity){final Resources base=activity.getResources();final Resources resources=new Resources(base.getAssets(),base.getDisplayMetrics(),base.getConfiguration()){@Override public int getIdentifier(String name,String type,String pkg){int found=id(name);return found!=0?found:super.getIdentifier(name,type,pkg);}};return new ContextWrapper(activity){@Override public Resources getResources(){return resources;}};}
 static void layout(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 static class Fixture{
  Activity activity;Context c;FrameLayout decor,content,layer;RelativeLayout root,frame;LinearLayout bar,tools,controller,bottom;TextView title;SeekBar seek;View info;t renderer;LinearLayout comments;int clicks,originalControllerIndex,originalBottomIndex;
  Fixture(boolean held){activity=Robolectric.buildActivity(Activity.class).setup().visible().get();c=context(activity);PreferenceManager.getDefaultSharedPreferences(c).edit().putString("player_controls_visibility_mode",held?"both":"off").commit();decor=new FrameLayout(c);content=new FrameLayout(c);decor.addView(content,new FrameLayout.LayoutParams(1955,919));root=new RelativeLayout(c);content.addView(root,new FrameLayout.LayoutParams(-1,-1));frame=new RelativeLayout(c);frame.setId(id("videoLayout"));root.addView(frame,new RelativeLayout.LayoutParams(-1,-1));comments=new LinearLayout(c);comments.setId(id("commentlay"));frame.addView(comments,new RelativeLayout.LayoutParams(-1,-1));renderer=new t(c);renderer.setClipBounds(new android.graphics.Rect(1000,0,1500,80));comments.addView(renderer,new LinearLayout.LayoutParams(720,80));controller=new LinearLayout(c);controller.setId(id("controller"));controller.setOrientation(LinearLayout.VERTICAL);controller.setBackgroundColor(0x77000000);controller.setPadding(8,0,8,8);TextView time=new TextView(c);time.setText("00:43                                   15:24");controller.addView(time,new LinearLayout.LayoutParams(-1,32));seek=new SeekBar(c);seek.setId(id("seekBar"));seek.setMax(100);controller.addView(seek,new LinearLayout.LayoutParams(-1,40));RelativeLayout.LayoutParams cp=new RelativeLayout.LayoutParams(1955,-2);cp.addRule(RelativeLayout.ALIGN_PARENT_BOTTOM);frame.addView(controller,cp);bottom=new LinearLayout(c);bottom.setId(id("bottommenulay"));bottom.setGravity(Gravity.RIGHT);View post=new View(c);bottom.addView(post,new LinearLayout.LayoutParams(48,40));info=new View(c);info.setClickable(true);info.setOnClickListener(new View.OnClickListener(){public void onClick(View v){clicks++;}});bottom.addView(info,new LinearLayout.LayoutParams(48,40));RelativeLayout.LayoutParams bp=new RelativeLayout.LayoutParams(-1,40);bp.addRule(RelativeLayout.ABOVE,id("controller"));frame.addView(bottom,bp);originalControllerIndex=frame.indexOfChild(controller);originalBottomIndex=frame.indexOfChild(bottom);layer=new FrameLayout(c);decor.addView(layer,new FrameLayout.LayoutParams(-1,-1));bar=new LinearLayout(c);bar.setGravity(Gravity.CENTER_VERTICAL);title=new TextView(c);title.setText("A long video title");title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);bar.addView(title,new LinearLayout.LayoutParams(0,40,1));tools=new LinearLayout(c);for(int i=0;i<6;i++)tools.addView(new View(c),new LinearLayout.LayoutParams(44,40));bar.addView(tools,new LinearLayout.LayoutParams(-2,40));layer.addView(bar,new FrameLayout.LayoutParams(-1,40,Gravity.TOP));activity.setContentView(decor);layout(decor,2048,955);}
  void update(int w,int h){FullscreenViewport205.update(root,decor,bar);FullscreenViewport205.top(root,bar,tools,tools,title);layout(decor,w,h);FullscreenViewport205.update(root,decor,bar);layout(decor,w,h);}
 }
 @Test public void barsReachPhysicalEdgesWhenContentParentIsNarrower(){Fixture f=new Fixture(false);assertEquals(1955,f.controller.getRight());f.update(2048,955);assertSame(f.layer,f.controller.getParent());assertSame(f.layer,f.bottom.getParent());assertEquals(0,f.controller.getLeft());assertEquals(2048,f.controller.getRight());assertEquals(955,f.controller.getBottom());assertEquals(2048,f.bottom.getRight());assertEquals(f.controller.getTop(),f.bottom.getBottom());assertEquals(0,f.bar.getLeft());assertEquals(2048,f.bar.getRight());assertEquals(0x77000000,((ColorDrawable)f.bar.getBackground()).getColor());assertEquals(0,((ColorDrawable)f.tools.getBackground()).getColor());assertEquals(Math.round(12*f.c.getResources().getDisplayMetrics().density),f.title.getPaddingLeft());assertEquals(f.title.getPaddingLeft(),f.seek.getPaddingLeft());assertEquals(f.seek.getPaddingLeft(),f.seek.getPaddingRight());assertTrue(f.seek.getPaddingLeft()>0);assertEquals(2048,f.seek.getWidth());f.seek.setProgress(0);int thumbStart=f.seek.getThumb().getBounds().centerX()+f.seek.getPaddingLeft()-f.seek.getThumbOffset();f.seek.setProgress(100);int thumbEnd=f.seek.getThumb().getBounds().centerX()+f.seek.getPaddingLeft()-f.seek.getThumbOffset();assertTrue(thumbStart>0);assertTrue(thumbEnd<2048);assertEquals(thumbStart,2048-thumbEnd);
  float x=2048-20,y=f.bottom.getTop()+20;f.layer.dispatchTouchEvent(MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,x,y,0));f.layer.dispatchTouchEvent(MotionEvent.obtain(0,1,MotionEvent.ACTION_UP,x,y,0));org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals("Right-edge button must remain tappable outside old content bounds",1,f.clicks);f.update(2048,955);assertEquals(2048,f.controller.getRight());assertEquals(955,f.controller.getBottom());System.out.println("205 coords: content.right=1955 screen.right="+f.controller.getRight()+" controller.bottom="+f.controller.getBottom()+" seek.inset="+f.seek.getPaddingLeft()+" title.inset="+f.title.getPaddingLeft());FullscreenViewport205.restore(f.root);assertSame(f.frame,f.controller.getParent());assertSame(f.frame,f.bottom.getParent());assertEquals(f.originalControllerIndex,f.frame.indexOfChild(f.controller));assertEquals(f.originalBottomIndex,f.frame.indexOfChild(f.bottom));assertEquals(1955,f.controller.getLayoutParams().width);assertEquals(8,f.controller.getPaddingBottom());}
 @Test public void previousVersionReproducesRightAndBottomGaps(){Fixture f=new Fixture(false);FullscreenViewport204.update(f.root,f.decor,f.bar);layout(f.decor,2048,955);assertEquals(1955,f.controller.getRight());assertEquals(919,f.controller.getBottom());assertSame(f.frame,f.controller.getParent());FullscreenViewport204.restore(f.root);}
 @Test public void rendererUsesItsWholeMeasuredAreaAfterRotation(){Fixture f=new Fixture(true);f.update(2048,955);assertNull(f.renderer.getClipBounds());assertEquals(f.renderer.getWidth(),f.renderer.drawingWidth,0);assertEquals(f.renderer.getHeight(),f.renderer.drawingHeight,0);assertEquals(f.comments.getWidth(),f.renderer.getWidth());assertTrue(f.renderer.getWidth()>1500);f.update(955,2048);assertNull(f.renderer.getClipBounds());assertEquals(f.renderer.getWidth(),f.renderer.drawingWidth,0);assertEquals(f.renderer.getHeight(),f.renderer.drawingHeight,0);FullscreenViewport205.restore(f.root);}
 @Test public void rotationAndHeldControlsKeepBottomAligned(){Fixture f=new Fixture(true);f.update(2048,955);f.update(955,2048);assertEquals(955,f.controller.getRight());assertEquals(2048,f.controller.getBottom());assertEquals(f.controller.getTop(),f.bottom.getBottom());f.update(2048,955);assertEquals(2048,f.controller.getRight());assertEquals(955,f.controller.getBottom());FullscreenViewport205.restore(f.root);}
}
